                    "sql": "CREATE OR REPLACE TABLE `hyuman-wh.maplemonk.hyuman_ESHOPBOX_fact_items_intermediate` AS SELECT CAST(NULL AS INT64) AS customer_id, COALESCE( JSON_EXTRACT_SCALAR(customerDetails, \'$.billingPostalCode\'), JSON_EXTRACT_SCALAR(customerDetails, \'$.shippingPostalCode\') ) AS pincode, JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\') AS marketplace, account AS source, customerOrderNumber AS order_id, customerOrderNumber AS reference_code, JSON_EXTRACT_SCALAR(customerDetails, \'$.billingContactPhone\') AS phone, JSON_EXTRACT_SCALAR(customerDetails, \'$.billingCustomerName\') AS name, JSON_EXTRACT_SCALAR(customerDetails, \'$.billingEmail\') AS email, DATETIME(TIMESTAMP_MILLIS(CAST(updatedAt AS INT64)), \"Asia/Kolkata\") AS SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(orderItemDetails, \'$.sku\') AS sku, CASE WHEN JSON_EXTRACT_SCALAR(orderItemDetails, \'$.combo\') = \'Yes\' THEN JSON_EXTRACT_SCALAR(orderItemDetails, \'$.sku\') ELSE NULL END AS bundle_sku_code, COALESCE( JSON_EXTRACT_SCALAR(orderItemDetails, \'$.esin\'), JSON_EXTRACT_SCALAR(orderItemDetails, \'$.sku\') ) AS Marketplace_sku, orderItemID AS product_id, JSON_EXTRACT_SCALAR(orderItemDetails, \'$.productName\') AS product_name, \'INR\' AS currency, JSON_EXTRACT_SCALAR(customerDetails, \'$.billingCity\') AS city, JSON_EXTRACT_SCALAR(customerDetails, \'$.billingState\') AS state, orderStatus AS ORDER_STATUS, currentOrderStatus AS sale_order_status, JSON_EXTRACT_SCALAR(shipmentDetails, \'$.invoiceNumber\') AS invoiceCode, DATETIME(TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(shipmentDetails, \'$.invoiceDate\') AS INT64)), \"Asia/Kolkata\") AS invoiceDate, DATETIME(TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(orderDetails, \'$.orderDate\') AS INT64)), \"Asia/Kolkata\") as order_date, DATETIME(TIMESTAMP_MILLIS(CAST(orderReceivedOn AS INT64)), \"Asia/Kolkata\") AS eshopbox_order_date, CAST(JSON_EXTRACT_SCALAR(erpDetails, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, 1 AS SUBORDER_QUANTITY, 0.0 AS discount, ( COALESCE(CAST(JSON_EXTRACT_SCALAR(erpDetails, \'$.cgstAmt\') AS FLOAT64), 0) + COALESCE(CAST(JSON_EXTRACT_SCALAR(erpDetails, \'$.sgstAmt\') AS FLOAT64), 0) + COALESCE(CAST(JSON_EXTRACT_SCALAR(erpDetails, \'$.igstAmt\') AS FLOAT64), 0) ) AS tax, CAST(JSON_EXTRACT_SCALAR(erpDetails, \'$.sellingPrice\') AS FLOAT64) AS SELLING_PRICE, JSON_EXTRACT_SCALAR(shipmentDetails, \'$.shipmentNumber\') AS shippingPackageCode, JSON_EXTRACT_SCALAR(shipmentTrackingDetails, \'$.delayedDeliveryTag\') AS shippingPackageStatus, orderItemID AS saleOrderItemCode, CAST(orderItemId_PK AS STRING) AS SALES_ORDER_ITEM_ID, JSON_EXTRACT_SCALAR(shipmentDetails, \'$.trackingId\') AS AWB, JSON_EXTRACT_SCALAR(shipmentDetails, \'$.facilityCode\') AS warehouse_name, CASE WHEN JSON_EXTRACT_SCALAR(orderDetails, \'$.isCod\') IN (\'1\', \'true\') THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, CASE WHEN JSON_EXTRACT_SCALAR(orderDetails, \'$.isCod\') IN (\'1\', \'true\') THEN \'COD\' ELSE \'Prepaid\' END AS payment_method, JSON_EXTRACT_SCALAR(shipmentDetails, \'$.courierName\') AS courier, transactionStatus AS shipping_status, CASE WHEN LOWER(orderStatus) NOT IN (\'cancelled\', \'returned\') THEN 1 ELSE 0 END AS shippedQuantity, DATETIME(TIMESTAMP_MILLIS(CAST(firstRTSTimestamp AS INT64)), \"Asia/Kolkata\") AS Dispatch_date, CASE WHEN LOWER(orderStatus) LIKE \'%deliver%\' THEN DATETIME(TIMESTAMP_MILLIS(CAST(updatedAt AS INT64)), \"Asia/Kolkata\") ELSE NULL END AS Delivered_Date, CASE WHEN LOWER(orderStatus) LIKE \'%return%\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN LOWER(orderStatus) LIKE \'%return%\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN LOWER(orderStatus) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, CAST(NULL AS INT64) AS new_customer_flag, CAST(NULL AS STRING) AS acquisition_product, DATE_DIFF( COALESCE(DATE(TIMESTAMP_MILLIS(CAST(updatedAt AS INT64)), \"Asia/Kolkata\"), CURRENT_DATE(\"Asia/Kolkata\")), DATE(TIMESTAMP_MILLIS(CAST(orderReceivedOn AS INT64)), \"Asia/Kolkata\"), DAY ) AS days_in_shipment, CASE WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%MEESHO%\' THEN \'Meesho\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%FLIPKART%\' THEN \'Flipkart\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%AJIO%\' THEN \'Ajio\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%MYNTRA%\' THEN \'Myntra\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%AMAZON%\' THEN \'Amazon\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) LIKE \'%SHOPIFY%\' THEN \'Shopify\' WHEN UPPER(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\')) = \'TATACLIQ1\' THEN \'TataCliq\' ELSE COALESCE(JSON_EXTRACT_SCALAR(orderDetails, \'$.portalName\'), \'Others\') END AS mapped_marketplace, DATE(TIMESTAMP_MILLIS(CAST(orderReceivedOn AS INT64)), \"Asia/Kolkata\") AS acquisition_date, JSON_EXTRACT_SCALAR(orderItemDetails, \'$.sku\') AS SKU_CODE FROM maplemonk.eshopbox_hyuman_get_orders qualify row_number() over (Partition by customerOrderNumber,orderItemID order by DATETIME(TIMESTAMP_MILLIS(CAST(updatedAt AS INT64)), \"Asia/Kolkata\") desc) =1; CREATE OR REPLACE TABLE `hyuman-wh.maplemonk.hyuman_ESHOPBOX_fact_items` AS select efi.*, case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_name) else UPPER(p.PRODUCT_name) end AS PRODUCT_NAME_Final, p.product_sub_category, coalesce(sm.commonsku,sm1.commonsku,case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_code) else UPPER(p.commonsku) end) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.mrp, case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.category_name) else upper(p.category) end AS Product_category, coalesce(pmt.type,pm.type) as type, case when upper(efi.marketplace) like \'%MEESHO%\' then 55 when upper(efi.marketplace) like \'%FLIPKART%\' then ifnull(src.shipping_rate,0) end as shipping_rate from `hyuman-wh.maplemonk.hyuman_ESHOPBOX_fact_items_intermediate` efi left join ( select trim(upper(product_id)) as product_id, trim(upper(marketplace)) as marketplace, trim(upper(primarykey)) as commonsku, from maplemonk.gs_hyuman_sku_master qualify row_number() over (partition by trim(product_id),trim(upper(marketplace)) order by 1 desc) = 1 ) sm on upper(sm.product_id) = upper(efi.sku) and upper(sm.marketplace) = upper(efi.marketplace) left join ( select trim(upper(product_id)) as product_id, trim(upper(primarykey)) as commonsku, from maplemonk.gs_hyuman_sku_master where marketplace = \'\' qualify row_number() over (partition by trim(product_id) order by 1 desc) = 1 ) sm1 on upper(sm1.product_id) = upper(efi.sku) LEFT JOIN ( SELECT product_code AS commonsku, cast(null as string) as color_sku, product_code as parent_sku, PRODUCT_name, category, CAST(NULL AS STRING) AS product_sub_category, CAST(NULL AS STRING) AS image_url, MRP FROM `hyuman-wh.maplemonk.Final_sku_master` ) p ON LOWER(coalesce(sm.commonsku,efi.sku)) = LOWER(p.commonsku) left join (select product_code, type from ( select product_code, type, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1) pm on lower(pm.product_Code) = lower(efi.bundle_sku_code) or lower(pm.product_Code) = lower(coalesce(sm.commonsku,efi.sku)) left join (select * from ( select product_code, type, name as product_name, Brand, category_name, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1 ) pmt on upper(pmt.product_code) = upper(efi.bundle_sku_code) or upper(pmt.product_code) = upper(coalesce(sm.commonsku,efi.sku)) LEFT JOIN (SELECT * FROM ( SELECT upper(trim(Master_SKU_Code)) AS commonsku, upper(trim(Flipkart_SKU_Code)) as fk_sku, cast(shipping_rate as float64) as shipping_rate, ROW_NUMBER() OVER (PARTITION BY upper(trim(Master_SKU_Code)) ORDER BY LENGTH(COALESCE(Master_SKU_Code,\'\')) DESC) rw FR